<?php

declare(strict_types=1);

use App\Http\Controllers\Auth\ForgotPasswordController;
use App\Http\Controllers\Auth\LoginController;
use App\Http\Controllers\Auth\RegisterController;
use App\Http\Controllers\Auth\ResetPasswordController;
use App\Http\Middleware\Authenticate;
use App\Http\Middleware\RedirectIfAuthenticated;
use Sahil\Http\Route;

/**
 * Authentication and dashboard routes, generated by `php sahil unda:auth`.
 *
 * App\Providers\WebRoutesProvider loads this file after routes/web.php. The
 * guest routes are wrapped in RedirectIfAuthenticated; the form endpoints
 * validate input, call the framework's auth services, and redirect.
 */
return [
    Route::get('/login', [LoginController::class, 'showLoginForm'])
        ->middleware(RedirectIfAuthenticated::class)
        ->name('login'),
    Route::post('/login', [LoginController::class, 'login'])
        ->middleware(RedirectIfAuthenticated::class)
        ->name('login.store'),

    Route::get('/register', [RegisterController::class, 'showRegistrationForm'])
        ->middleware(RedirectIfAuthenticated::class)
        ->name('register'),
    Route::post('/register', [RegisterController::class, 'register'])
        ->middleware(RedirectIfAuthenticated::class)
        ->name('register.store'),

    Route::get('/forgot-password', [ForgotPasswordController::class, 'showLinkRequestForm'])
        ->middleware(RedirectIfAuthenticated::class)
        ->name('password.request'),
    Route::post('/forgot-password', [ForgotPasswordController::class, 'sendResetLinkEmail'])
        ->middleware(RedirectIfAuthenticated::class)
        ->name('password.email'),

    Route::get('/reset-password/{token}', [ResetPasswordController::class, 'showResetForm'])
        ->middleware(RedirectIfAuthenticated::class)
        ->name('password.reset'),
    Route::post('/reset-password', [ResetPasswordController::class, 'reset'])
        ->middleware(RedirectIfAuthenticated::class)
        ->name('password.update'),

    Route::post('/logout', [LoginController::class, 'logout'])
        ->middleware(Authenticate::class)
        ->name('logout'),

    Route::get('/dashboard', [LoginController::class, 'showDashboard'])
        ->middleware(Authenticate::class)
        ->name('dashboard'),
];
